using LocalPro.Web.Domain;using LocalPro.Web.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace LocalPro.Web.Pages.Requests;[Authorize]public class TrackModel(RequestService service):PageModel{public ServiceRequest Item{get;set;}=null!;public async Task<IActionResult> OnGetAsync(int id){try{Item=await service.Get(User,id);return Page();}catch(RuleException){return NotFound();}}public async Task<IActionResult> OnPostAsync(int id,string action){try{await service.Change(User,id,action);}catch(RuleException ex){TempData["Error"]=ex.Message;}return RedirectToPage(new{id});}public async Task<IActionResult> OnGetPhotoAsync(int id){try{var p=await service.Photo(User,id);Response.Headers.CacheControl="private, no-store";return File(p.Bytes,p.Type);}catch(RuleException){return NotFound();}}public async Task<IActionResult> OnGetFeedAsync(int id){try{return new JsonResult(RequestService.Dto(await service.Get(User,id),User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value));}catch(RuleException){return NotFound();}}}
